namespace sv_0b6b4e508e9349a7853e780e5db91985.Services;

public class WarehouseState
{
    private string _selectedWarehouseId = "WH-001";

    public string SelectedWarehouseId => _selectedWarehouseId;

    public string SelectedWarehouseName =>
        Warehouses.FirstOrDefault(w => w.Id == _selectedWarehouseId)?.Name ?? "Unknown";

    public event Action? OnChange;

    public static readonly IReadOnlyList<WarehouseInfo> Warehouses =
    [
        new("WH-001", "Warehouse A — Main Distribution"),
        new("WH-002", "Warehouse B — Cold Storage"),
        new("WH-003", "Warehouse C — Overflow"),
    ];

    public void SetWarehouse(string warehouseId)
    {
        if (_selectedWarehouseId == warehouseId) return;
        _selectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

public record WarehouseInfo(string Id, string Name);

namespace sv_0b6b4e508e9349a7853e780e5db91985.Services;

public class InventoryAlertService
{
    private int _lastLowStockCount;

    public int LowStockCount => _lastLowStockCount;

    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning the number of items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate variability per warehouse by using the hash as part of the seed
        var seed = Environment.TickCount ^ warehouseId.GetHashCode();
        var count = Random.Shared.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Updates the cached count and notifies all subscribers.
    /// </summary>
    public void UpdateCount(int newCount)
    {
        _lastLowStockCount = newCount;
        OnAlertCountChanged?.Invoke();
    }
}

