@page "/dashboard"
@inject sv_0b6b4e508e9349a7853e780e5db91985.Services.WarehouseState WarehouseState
@inject sv_0b6b4e508e9349a7853e780e5db91985.Services.InventoryAlertService AlertService
@implements IAsyncDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-header">
                <strong>@WarehouseState.SelectedWarehouseName</strong>
            </div>
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4">
                    @if (_loading)
                    {
                        <span class="spinner-border spinner-border-sm" role="status"></span>
                    }
                    else
                    {
                        @AlertService.LowStockCount
                    }
                </p>
                <p class="text-muted">Items below minimum stock level</p>
                <p class="small text-muted">Polling every 10 seconds&hellip; Last updated: @_lastUpdated?.ToString("HH:mm:ss")</p>
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;
    private bool _loading = true;
    private DateTime? _lastUpdated;
    private Action? _warehouseChangedHandler;

    protected override async Task OnInitializedAsync()
    {
        _warehouseChangedHandler = () => InvokeAsync(OnWarehouseChanged);
        WarehouseState.OnChange += _warehouseChangedHandler;

        await PollOnceAsync();
        StartPolling();
    }

    private async void OnWarehouseChanged()
    {
        // Restart polling with new warehouse
        await StopPollingAsync();
        _loading = true;
        StateHasChanged();

        await PollOnceAsync();
        StartPolling();
        StateHasChanged();
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await PollOnceAsync();
                await InvokeAsync(StateHasChanged);
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose or warehouse change
        }
    }

    private async Task PollOnceAsync()
    {
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.SelectedWarehouseId);
        AlertService.UpdateCount(count);
        _lastUpdated = DateTime.Now;
        _loading = false;
    }

    private async Task StopPollingAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_warehouseChangedHandler is not null)
        {
            WarehouseState.OnChange -= _warehouseChangedHandler;
        }
        await StopPollingAsync();
    }
}

